// 语言切换模块 (ES Module)
// 移除图片依赖，使用 FontAwesome 图标 + 文字

const LanguageSwitcher = {
    currentLanguage: "zh",
    
    init: function() {
        const savedLang = this.getCookie("language") || "zh";
        this.currentLanguage = savedLang;
        this.applyLanguage(this.currentLanguage);
    },

    switchLanguage: function() {
        this.currentLanguage = this.currentLanguage === "zh" ? "en" : "zh";
        this.setCookie("language", this.currentLanguage, 30);
        this.applyLanguage(this.currentLanguage);
        
        // 触发自定义事件，通知其他模块（如 nav-core.js）语言已变更
        const event = new CustomEvent("navLanguageChanged", {
            detail: { language: this.currentLanguage }
        });
        document.dispatchEvent(event);
    },

    applyLanguage: function(lang) {
        // 更新切换按钮的 UI
        this.updateLanguageUI(lang);
        
        // 设置 HTML 标签的 lang 属性
        document.documentElement.lang = lang === "zh" ? "zh-CN" : "en";
    },

    updateLanguageUI: function(lang) {
        // 获取所有需要更新的目标元素（兼容 ID 和 Class）
        const texts = new Set();
        const idText = document.getElementById("lang-text");
        if (idText) texts.add(idText);
        document.querySelectorAll(".lang-text-element").forEach(el => texts.add(el));

        // 提示文本显示“切换到目标语言”
        const textContent = lang === "zh" ? "Switch to English" : "Switch to Chinese";
        
        texts.forEach(text => {
            text.textContent = textContent;
        });

        // 也可以更新图标，如果需要的话
        // const icons = new Set(); ...
    },

    setCookie: function(name, value, days) {
        let expires = "";
        if (days) {
            const date = new Date();
            date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
            expires = "; expires=" + date.toUTCString();
        }
        document.cookie = name + "=" + (value || "") + expires + "; path=/";
    },

    getCookie: function(name) {
        const nameEQ = name + "=";
        const ca = document.cookie.split(';');
        for (let i = 0; i < ca.length; i++) {
            let c = ca[i];
            while (c.charAt(0) === ' ') c = c.substring(1, c.length);
            if (c.indexOf(nameEQ) === 0) return c.substring(nameEQ.length, c.length);
        }
        return null;
    }
};

// 暴露给全局
window.languageSwitcher = LanguageSwitcher;

// 自动初始化
if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => LanguageSwitcher.init());
} else {
    LanguageSwitcher.init();
}

export default LanguageSwitcher;
